import{printedArtwork}from'../../modeling/artwork.js';import{spec}from'./dimensions.js';const sources={front:new URL('./reference-redraw-front.png',import.meta.url).href,back:new URL('./reference-redraw-back.png',import.meta.url).href,dip:new URL('./reference-redraw-dip.png',import.meta.url).href};export function addStickers(host){const layers=[];for(const face of['front','back','dip']){const v=spec.labels[face],position=[...v.position];if(face==='front')position[2]+=.04;layers.push(...printedArtwork(host,{target:face==='dip'?host.lora433Assembly.controls.cover:host.lora433Assembly.labels[face],url:sources[face],size:v.size,position,face:face==='back'?'back':'front',depth:.1,name:'LoRa433 own '+face+' official-photo code redraw',artworkKind:'reference-redraw'})??[]);}return layers;}
